#!/usr/bin/env python3
"""
Round 175b (culprits-tiles-more), 4 October 2026.

oceans_more.py: ocean acidity from the models' median. ocean_stressors.py:
each pressure read from its own KNB package. Whole files, each written only
if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {
    "scripts/oceans_more.py": "",
    "scripts/ocean_stressors.py": "",
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"round175b_tiles: {name} already up to date")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"round175b_tiles: wrote {name}")


if __name__ == "__main__":
    main()
